def embed_input_ids(self, input_ids: torch.Tensor) -> torch.Tensor:
    return self.model.embed_input_ids(input_ids)

def compute_logits(
    self,
    hidden_states: torch.Tensor,
) -> torch.Tensor | None:
    logits = self.logits_processor(self.lm_head, hidden_states)
    return logits

def forward(
    self,
    input_ids: torch.Tensor,
    positions: torch.Tensor,
    intermediate_tensors: IntermediateTensors | None = None,
    inputs_embeds: torch.Tensor | None = None,
) -> torch.Tensor | IntermediateTensors:
    hidden_states = self.model(
        input_ids, positions, intermediate_tensors, inputs_embeds
    )
    return hidden_states

def get_mtp_target_hidden_states(self) -> torch.Tensor | None:
    """Pre-hc_head residual stream buffer (max_num_batched_tokens,
    hc_mult * hidden_size) for the MTP draft model. Populated by
    forward(); valid after each target step."""
    return getattr(self.model, "_mtp_hidden_buffer", None)

def load_weights(self, weights: Iterable[tuple[str, torch.Tensor]]) -> set[str]:
    loader = AutoWeightsLoader(self, skip_substrs=["mtp."])
    loaded_params = loader.load_weights(weights, mapper=self.hf_to_vllm_mapper)
    self.model.finalize_mega_moe_weights()
    self.model.finalize_mhc_broadcast_weights()
    return loaded_params

def get_expert_mapping(self) -> list[tuple[str, str, int, str]]:
    return self.model.get_expert_mapping()

def forward(
    self,
    input_ids: torch.Tensor,
    positions: torch.Tensor,
    intermediate_tensors: IntermediateTensors | None,
    inputs_embeds: torch.Tensor | None = None,
) -> torch.Tensor | IntermediateTensors:
    if get_pp_group().is_first_rank:
        if inputs_embeds is not None:
            hidden_states = inputs_embeds
        else:
            hidden_states = self.embed_input_ids(input_ids)
    else:
        assert intermediate_tensors is not None
        hidden_states = intermediate_tensors["hidden_states"]

    if self.use_mega_moe:
        input_ids = input_ids.to(torch.int64)

    full_num_tokens = positions.shape[0]
    if self.use_sequence_parallel:
        if envs.VLLM_MOE_SKIP_PADDING and is_forward_context_available():
            forward_context = get_forward_context()
            forward_context.is_padding = sp_padding_mask(
                forward_context.is_padding, hidden_states
            )
        hidden_states = sp_shard(hidden_states)
        input_ids = sp_shard(input_ids)

    residual, post_mix, res_mix = None, None, None
    aux_hidden_states: list[torch.Tensor] = []
    final_aux_recon: torch.Tensor | None = None  # avoid duplicate mhc_post call
    for idx, layer in enumerate(
        islice(self.layers, self.start_layer, self.end_layer),
        start=self.start_layer,
    ):
        hidden_states, residual, post_mix, res_mix = layer(
            hidden_states,
            positions,
            input_ids,
            post_mix,
            res_mix,
            residual,
        )
        if idx + 1 in self.aux_hidden_state_layers:
            # Reconstruct the aux hidden state for draft models
            aux_recon = mhc_post_tilelang(
                hidden_states, residual, post_mix, res_mix
            )
            aux_hidden_state = aux_recon.mean(dim=1)
            if self.use_sequence_parallel:
                aux_hidden_state = sp_all_gather(aux_hidden_state)[:full_num_tokens]
            aux_hidden_states.append(aux_hidden_state)
            final_aux_recon = aux_recon
    if layer is not None:
        # Reuse if the last layer was captured as an aux hidden state
        if self.end_layer in self.aux_hidden_state_layers:
            hidden_states = final_aux_recon
        else:
            hidden_states = mhc_post_tilelang(
                hidden_states, residual, post_mix, res_mix
            )

    if not get_pp_group().is_last_rank:
        return IntermediateTensors({"hidden_states": hidden_states})

    if self.use_sequence_parallel:
        hidden_states = sp_all_gather(hidden_states)[:full_num_tokens]

    if self._mtp_hidden_buffer is not None:
        num_tokens = hidden_states.shape[0]
        self._mtp_hidden_buffer[:num_tokens].copy_(hidden_states.flatten(1))

    hidden_states = hc_head_fused_kernel_tilelang(
        hidden_states,
        self.hc_head_fn,
        self.hc_head_scale,
        self.hc_head_base,
        self.rms_norm_eps,
        self.hc_eps,
    )
    hidden_states = self.norm(hidden_states)
    if len(aux_hidden_states) > 0:
        return hidden_states, aux_hidden_states
    return hidden_states

class DeepseekV4FlashMLAAttention(DeepseekV4Attention):
    """FlashMLA sparse MLA attention layer for DeepSeek V4 (CUDA)."""

    backend_cls = DeepseekV4FlashMLABackend

    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)
        self._einsum_recipe, self._tma_aligned_scales = compute_fp8_einsum_recipe()

    def _o_proj(self, o: torch.Tensor, positions: torch.Tensor) -> torch.Tensor:
        return deep_gemm_fp8_o_proj(
            o,
            positions,
            self.rotary_emb.cos_sin_cache,
            self.wo_a,
            self.wo_b,
            n_groups=self.n_local_groups,
            heads_per_group=self.n_local_heads // self.n_local_groups,
            nope_dim=self.nope_head_dim,
            rope_dim=self.rope_head_dim,
            o_lora_rank=self.o_lora_rank,
            einsum_recipe=self._einsum_recipe,
            tma_aligned_scales=self._tma_aligned_scales,
        )

    @classmethod
    def get_padded_num_q_heads(cls, num_heads: int) -> int:
        # FP8 decode kernel only supports h_q = 64 or 128.
        if num_heads > 128:
            raise ValueError(
                f"DeepseekV4 FlashMLA does not support {num_heads} heads "
                "(FP8 decode kernel requires h_q in {64, 128})."
            )
        return 64 if num_heads <= 64 else 128

def forward(
    self, hidden_states: torch.Tensor, input_ids: torch.Tensor | None = None
) -> torch.Tensor:
    if self.gate.tid2eid is not None and input_ids is None:
        raise ValueError("DeepSeek V4 hash MoE routing requires input_ids.")

    if not self.use_mega_moe:
        return self._forward_fused_moe(hidden_states, input_ids)

    org_shape = hidden_states.shape
    router_logits, _ = self.gate(hidden_states)
    topk_weights, topk_ids = fused_topk_bias(
        hidden_states=hidden_states,
        gating_output=router_logits,
        scoring_func=self.scoring_func,
        e_score_correction_bias=self.gate.e_score_correction_bias.data
        if self.gate.e_score_correction_bias is not None
        else None,
        topk=self.n_activated_experts,
        renormalize=self.renormalize,
        indices_type=self.hash_indices_dtype,
        input_tokens=input_ids,
        hash_indices_table=self.gate.tid2eid,
        routed_scaling_factor=self.routed_scaling_factor,
    )
    activation_clamp = (
        float(self.swiglu_limit) if self.swiglu_limit is not None else None
    )
    final_hidden_states = self.experts(
        hidden_states,
        topk_weights,
        topk_ids,
        activation_clamp=activation_clamp,
    )

    if self.shared_experts is not None:
        shared_output = self.shared_experts(hidden_states)
        final_hidden_states += shared_output

    return final_hidden_states.view(org_shape)

def _forward_fused_moe(
    self, hidden_states: torch.Tensor, input_ids: torch.Tensor | None = None
) -> torch.Tensor:
    org_shape = hidden_states.shape
    if self.experts.is_internal_router:
        # In this case, the gate/router runs inside the MoERunner class
        final_hidden_states = self.experts(
            hidden_states=hidden_states,
            router_logits=hidden_states,
            input_ids=input_ids,
        )
    else:
        router_logits, _ = self.gate(hidden_states)
        final_hidden_states = self.experts(
            hidden_states=hidden_states,
            router_logits=router_logits,
            input_ids=input_ids,
        )

    return final_hidden_states.view(org_shape)

def _make_deepseek_v4_weights_mapper(expert_dtype: str) -> WeightsMapper:
    if expert_dtype == "fp4":
        # MXFP4 experts use Mxfp4MoEMethod, which registers scales as
        # ``w{1,2,3}_weight_scale`` (no _inv suffix). FP8 linear and
        # shared experts use Fp8LinearMethod's block scales, which
        # register as ``weight_scale_inv``.
        scale_regex = {
            re.compile(r"(\.experts\.\d+\.w[123])\.scale$"): r"\1.weight_scale",
            re.compile(r"\.scale$"): ".weight_scale_inv",
        }
    else:
        # FP8 experts use Fp8MoEMethod (block_quant=True), which registers
        # scales as ``w{13,2}_weight_scale_inv``. Map all ``.scale`` keys
        # there.
        scale_regex = {
            re.compile(r"\.scale$"): ".weight_scale_inv",
        }
    return WeightsMapper(
        orig_to_new_prefix={
            "layers.": "model.layers.",
            "embed.": "model.embed.",
            "norm.": "model.norm.",
            "hc_head": "model.hc_head",
            "mtp.": "model.mtp.",
        },
        orig_to_new_regex=scale_regex,
        orig_to_new_suffix={
            "head.weight": "lm_head.weight",
            "embed.weight": "embed_tokens.weight",
            ".ffn.gate.bias": ".ffn.gate.e_score_correction_bias",
        },
        orig_to_new_substr={
            ".shared_experts.w2": ".shared_experts.down_proj",
        },
    )

@classmethod
def override_quantization_method(
    cls, hf_quant_cfg, user_quant, hf_config=None
) -> QuantizationMethods | None:
    if not (
        isinstance(hf_quant_cfg, dict)
        and (
            hf_quant_cfg.get("quant_method") in ("fp8", "deepseek_v4_fp8")
            or (
                hf_quant_cfg.get("quant_method") == "quark"
                and cls._is_quark_mxfp4_ocp(hf_quant_cfg)
            )
        )
    ):
        return None
    model_type = getattr(hf_config, "model_type", None)
    if model_type == "deepseek_v4" or user_quant == "deepseek_v4_fp8":
        return "deepseek_v4_fp8"
    return None

def get_quant_method(self, layer, prefix):
    if isinstance(layer, RoutedExperts):
        if is_layer_skipped(
            prefix=prefix,
            ignored_layers=self.ignored_layers,
            fused_mapping=self.packed_modules_mapping,
        ):
            return UnquantizedFusedMoEMethod(layer.moe_config)
        if self.expert_dtype == "fp4":
            if self.moe_quant_algo == "NVFP4":
                from vllm.model_executor.layers.quantization.modelopt import (
                    ModelOptNvFp4FusedMoE,
                )

                return ModelOptNvFp4FusedMoE(
                    quant_config=self._get_nvfp4_config(),
                    moe_config=layer.moe_config,
                )
            return Mxfp4MoEMethod(layer.moe_config)
        # expert_dtype == "fp8": fall through to Fp8Config which
        # returns Fp8MoEMethod with block-wise float32 scales.
    return super().get_quant_method(layer, prefix)

def is_mxfp4_quant(self, prefix, layer):
    if not isinstance(layer, RoutedExperts) or self.expert_dtype != "fp4":
        return False
    return self.moe_quant_algo != "NVFP4"
